// PPh 23 Withholding Tax Calculator - Indonesia
// Tarif PPh 23:
//   - 2% untuk jasa (punya NPWP)
//   - 4% untuk jasa (tanpa NPWP / NPWP tidak valid)
//   - 15% untuk dividen, bunga, royalti

const items = $input.all();
const now = new Date();
const masaPajak = `${String(now.getMonth() === 0 ? 12 : now.getMonth()).padStart(2, '0')}/${now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear()}`;

function validateNPWP(npwp) {
  if (!npwp) return false;
  const cleaned = String(npwp).replace(/[^0-9]/g, '');
  // NPWP format: 15 digits (old) or 16 digits (NIK-based new format)
  return cleaned.length === 15 || cleaned.length === 16;
}

function formatNPWP(npwp) {
  const cleaned = String(npwp).replace(/[^0-9]/g, '');
  if (cleaned.length === 15) {
    return `${cleaned.slice(0,2)}.${cleaned.slice(2,5)}.${cleaned.slice(5,8)}.${cleaned.slice(8,9)}-${cleaned.slice(9,12)}.${cleaned.slice(12,15)}`;
  }
  return cleaned;
}

function formatRupiah(amount) {
  return 'Rp ' + Number(amount).toLocaleString('id-ID', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

function getTarifPPh23(jenisJasa, hasValidNPWP) {
  const jenisLower = String(jenisJasa).toLowerCase();
  if (['dividen', 'bunga', 'royalti', 'dividend', 'interest', 'royalty'].includes(jenisLower)) {
    return 0.15; // 15% for dividends, interest, royalties
  }
  // Jasa (services): 2% with NPWP, 4% without
  return hasValidNPWP ? 0.02 : 0.04;
}

let buktiPotongCounter = 1;
const results = [];
let totalPPh23 = 0;

for (const item of items) {
  const d = item.json;
  const namaVendor = d.nama_vendor || d.vendor_name || '';
  const npwp = d.npwp || d.NPWP || '';
  const jenisJasa = d.jenis_jasa || d.service_type || 'jasa';
  const nilaiBruto = Number(d.nilai_bruto || d.gross_amount || 0);
  const noInvoice = d.no_invoice || d.invoice_number || '';
  const tanggalInvoice = d.tanggal_invoice || d.invoice_date || '';
  const tanggalBayar = d.tanggal_bayar || d.payment_date || '';

  const hasValidNPWP = validateNPWP(npwp);
  const tarifPPh23 = getTarifPPh23(jenisJasa, hasValidNPWP);
  const pph23Terutang = Math.round(nilaiBruto * tarifPPh23);
  const nilaiDibayar = nilaiBruto - pph23Terutang;

  const noBuktiPotong = `BP-${masaPajak.replace('/', '')}-${String(buktiPotongCounter).padStart(4, '0')}`;
  buktiPotongCounter++;
  totalPPh23 += pph23Terutang;

  results.push({
    json: {
      no_bukti_potong: noBuktiPotong,
      masa_pajak: masaPajak,
      nama_vendor: namaVendor,
      npwp: npwp,
      npwp_formatted: hasValidNPWP ? formatNPWP(npwp) : 'TIDAK VALID / BELUM ADA',
      npwp_valid: hasValidNPWP,
      jenis_jasa: jenisJasa,
      no_invoice: noInvoice,
      tanggal_invoice: tanggalInvoice,
      tanggal_bayar: tanggalBayar,
      nilai_bruto: nilaiBruto,
      nilai_bruto_formatted: formatRupiah(nilaiBruto),
      tarif_pph23: tarifPPh23,
      tarif_pph23_persen: `${(tarifPPh23 * 100).toFixed(0)}%`,
      pph23_terutang: pph23Terutang,
      pph23_terutang_formatted: formatRupiah(pph23Terutang),
      nilai_dibayar: nilaiDibayar,
      nilai_dibayar_formatted: formatRupiah(nilaiDibayar),
      keterangan: !hasValidNPWP ? 'Tarif lebih tinggi (100%) karena tidak memiliki NPWP valid' : '',
      tanggal_potong: now.toISOString().split('T')[0],
      total_pph23_bulan_ini: totalPPh23,
      total_pph23_bulan_ini_formatted: formatRupiah(totalPPh23)
    }
  });
}

return results;

// Generate CSV in DJP e-Bupot PPh 23 format
// Columns sesuai format impor e-Bupot Unifikasi DJP

const items = $input.all();
const now = new Date();
const bulan = String(now.getMonth() === 0 ? 12 : now.getMonth()).padStart(2, '0');
const tahun = now.getMonth() === 0 ? now.getFullYear() - 1 : now.getFullYear();

// e-Bupot CSV Header
const csvHeaders = [
  'Tahun Pajak',
  'Masa Pajak',
  'Tin (NPWP/NIK)',
  'Nama',
  'Alamat',
  'Kode Objek Pajak',
  'Nomor Faktur/Dokumen',
  'Tanggal Dokumen',
  'Jumlah Penghasilan Bruto',
  'Tarif (%)',
  'Jumlah PPh Dipotong',
  'Nomor Bukti Potong',
  'Tanggal Bukti Potong',
  'Fasilitas'
];

function getKodeObjekPajak(jenisJasa) {
  const jenis = String(jenisJasa).toLowerCase();
  if (jenis === 'dividen' || jenis === 'dividend') return '24-100-01';
  if (jenis === 'bunga' || jenis === 'interest') return '24-100-02';
  if (jenis === 'royalti' || jenis === 'royalty') return '24-100-03';
  if (jenis.includes('teknik') || jenis.includes('technical')) return '24-104-01';
  if (jenis.includes('manajemen') || jenis.includes('management')) return '24-104-02';
  if (jenis.includes('konsultan') || jenis.includes('consult')) return '24-104-03';
  return '24-104-99'; // Jasa lainnya
}

function escapeCSV(val) {
  const str = String(val || '');
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

const csvRows = [csvHeaders.join(',')];

let totalBruto = 0;
let totalPPh = 0;

for (const item of items) {
  const d = item.json;
  totalBruto += d.nilai_bruto;
  totalPPh += d.pph23_terutang;

  const row = [
    tahun,
    bulan,
    escapeCSV(d.npwp),
    escapeCSV(d.nama_vendor),
    '',
    getKodeObjekPajak(d.jenis_jasa),
    escapeCSV(d.no_invoice),
    d.tanggal_invoice,
    d.nilai_bruto,
    (d.tarif_pph23 * 100).toFixed(0),
    d.pph23_terutang,
    escapeCSV(d.no_bukti_potong),
    d.tanggal_potong,
    d.npwp_valid ? '' : 'TANPA NPWP'
  ];
  csvRows.push(row.join(','));
}

const csvContent = csvRows.join('\n');
const filename = `eBupot_PPh23_${tahun}_${bulan}.csv`;

const summary = [
  `\n=== RINGKASAN PPh 23 - Masa Pajak ${bulan}/${tahun} ===`,
  `Jumlah Bukti Potong: ${items.length}`,
  `Total Penghasilan Bruto: Rp ${totalBruto.toLocaleString('id-ID')}`,
  `Total PPh 23 Terutang: Rp ${totalPPh.toLocaleString('id-ID')}`,
  `File: ${filename}`
].join('\n');

return [{
  json: {
    filename: filename,
    csv_content: csvContent,
    summary: summary,
    masa_pajak: `${bulan}/${tahun}`,
    total_bukti_potong: items.length,
    total_bruto: totalBruto,
    total_pph23: totalPPh,
    total_bruto_formatted: 'Rp ' + totalBruto.toLocaleString('id-ID'),
    total_pph23_formatted: 'Rp ' + totalPPh.toLocaleString('id-ID')
  }
}];
